import { spawnSync } from 'node:child_process';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Playwright global setup — runs ONCE per `ddev playwright test` invocation,
 * before any worker / spec starts.
 *
 * Reseeds the `test` database from the per-table CSV fixtures so every test
 * session begins from a known, deterministic state. The companion FE/BE
 * runtime routes Playwright requests to `test` via the X-Test-Run header
 * (see Build/config/system/additional.php, generated by setup-typo3.sh), so
 * what we seed here is what the SUT serves to the tests.
 *
 * Implementation: shells out to import-seeds.mjs with TYPO3_DB_NAME=test.
 * Keeps a single import path for both the bootstrap-time seed (setup-typo3.sh)
 * and the per-test-run reseed (here). The import script TRUNCATEs each
 * fixture table before loading, so this is fully idempotent and safe to
 * run on a database that has prior test residue.
 */
export default async function globalSetup() {
    const here = dirname(fileURLToPath(import.meta.url));
    const seedScript = resolve(here, 'import-seeds.mjs');

    console.log('[global-setup] Seeding `test` database for Playwright run ...');
    const result = spawnSync('node', [seedScript], {
        stdio: 'inherit',
        env: { ...process.env, TYPO3_DB_NAME: 'test' },
    });
    if (result.status !== 0) {
        throw new Error(`global-setup: import-seeds.mjs exited with status ${result.status}`);
    }
}
